{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TEMP TABLE parsed_orders AS WITH ranked AS ( SELECT _AIRBYTE_AB_ID, _AIRBYTE_EMITTED_AT, _AIRBYTE_NORMALIZED_AT, SUCCESSFUL, SALEORDERDTO, JSON_EXTRACT_SCALAR(SALEORDERDTO, \'$.code\') AS order_code, ROW_NUMBER() OVER ( PARTITION BY JSON_EXTRACT_SCALAR(SALEORDERDTO, \'$.code\') ORDER BY _AIRBYTE_NORMALIZED_AT DESC ) AS rn FROM `MapleMonk.UNICOMMERCE_Uni_KA_GET_ORDERS_BY_IDS_final` WHERE SUCCESSFUL = \'true\' ) SELECT * EXCEPT(rn) FROM ranked WHERE rn = 1; CREATE OR REPLACE TEMP TABLE order_header AS SELECT p._AIRBYTE_AB_ID, p._AIRBYTE_NORMALIZED_AT, p.SALEORDERDTO, JSON_EXTRACT_SCALAR(SALEORDERDTO, \'$.code\') AS order_code, JSON_EXTRACT_SCALAR(SALEORDERDTO, \'$.displayOrderCode\') AS display_order_code, JSON_EXTRACT_SCALAR(SALEORDERDTO, \'$.channel\') AS marketplace, JSON_EXTRACT_SCALAR(SALEORDERDTO, \'$.source\') AS source, JSON_EXTRACT_SCALAR(SALEORDERDTO, \'$.status\') AS order_status, JSON_EXTRACT_SCALAR(SALEORDERDTO, \'$.currencyCode\') AS currency, CAST(JSON_EXTRACT_SCALAR(SALEORDERDTO, \'$.cod\') AS BOOL) AS is_cod, TIMESTAMP_MILLIS(CAST(JSON_EXTRACT_SCALAR(SALEORDERDTO, \'$.created\') AS INT64)) AS order_created_ts, TIMESTAMP_MILLIS(CAST(JSON_EXTRACT_SCALAR(SALEORDERDTO, \'$.updated\') AS INT64)) AS order_updated_ts, TIMESTAMP_MILLIS(CAST(JSON_EXTRACT_SCALAR(SALEORDERDTO, \'$.displayOrderDateTime\') AS INT64)) AS order_display_ts, TIMESTAMP_MILLIS(CAST(JSON_EXTRACT_SCALAR(SALEORDERDTO, \'$.fulfillmentTat\') AS INT64)) AS fulfillment_tat_ts, JSON_EXTRACT_SCALAR(SALEORDERDTO, \'$.billingAddress.name\') AS billing_name, JSON_EXTRACT_SCALAR(SALEORDERDTO, \'$.billingAddress.addressLine1\') AS billing_address_line1, JSON_EXTRACT_SCALAR(SALEORDERDTO, \'$.billingAddress.addressLine2\') AS billing_address_line2, JSON_EXTRACT_SCALAR(SALEORDERDTO, \'$.billingAddress.city\') AS billing_city, JSON_EXTRACT_SCALAR(SALEORDERDTO, \'$.billingAddress.state\') AS billing_state, JSON_EXTRACT_SCALAR(SALEORDERDTO, \'$.billingAddress.pincode\') AS pincode, JSON_EXTRACT_SCALAR(SALEORDERDTO, \'$.billingAddress.country\') AS billing_country, JSON_EXTRACT_SCALAR(SALEORDERDTO, \'$.billingAddress.phone\') AS phone, JSON_EXTRACT_SCALAR(SALEORDERDTO, \'$.billingAddress.email\') AS email FROM parsed_orders p; CREATE OR REPLACE TEMP TABLE order_items AS SELECT oh.* EXCEPT(SALEORDERDTO), JSON_EXTRACT_SCALAR(item, \'$.code\') AS saleOrderItemCode, JSON_EXTRACT_SCALAR(item, \'$.id\') AS sales_order_item_id, JSON_EXTRACT_SCALAR(item, \'$.itemSku\') AS sku, JSON_EXTRACT_SCALAR(item, \'$.sellerSkuCode\') AS marketplace_sku, JSON_EXTRACT_SCALAR(item, \'$.itemName\') AS product_name, JSON_EXTRACT_SCALAR(item, \'$.statusCode\') AS item_status, JSON_EXTRACT_SCALAR(item, \'$.channelProductId\') AS channel_product_id, CAST(JSON_EXTRACT_SCALAR(item, \'$.sellingPrice\') AS FLOAT64) AS selling_price, CAST(JSON_EXTRACT_SCALAR(item, \'$.shippingCharges\') AS FLOAT64) AS shipping_price, CAST(JSON_EXTRACT_SCALAR(item, \'$.discount\') AS FLOAT64) AS discount, CAST(JSON_EXTRACT_SCALAR(item, \'$.totalIntegratedGst\') AS FLOAT64) AS tax_igst, CAST(JSON_EXTRACT_SCALAR(item, \'$.totalPrice\') AS FLOAT64) AS total_price, CAST(JSON_EXTRACT_SCALAR(item, \'$.cashOnDeliveryCharges\') AS FLOAT64) AS cod_charges, CAST(JSON_EXTRACT_SCALAR(item, \'$.packetNumber\') AS FLOAT64) AS suborder_quantity_raw, JSON_EXTRACT_SCALAR(item, \'$.facilityName\') AS warehouse_name, JSON_EXTRACT_SCALAR(item, \'$.facilityCode\') AS facility_code, JSON_EXTRACT_SCALAR(item, \'$.shelfCode\') AS shelf_code, JSON_EXTRACT_SCALAR(item, \'$.batchDTO.batchCode\') AS batch_code, JSON_EXTRACT_SCALAR(item, \'$.batchDTO.batchFieldsDTO.vendorBatchNumber\') AS vendor_batch_number, JSON_EXTRACT_SCALAR(item, \'$.batchDTO.batchFieldsDTO.vendorCode\') AS vendor_code, CAST(JSON_EXTRACT_SCALAR(item, \'$.batchDTO.batchFieldsDTO.mrp\') AS FLOAT64) AS batch_mrp, CAST(JSON_EXTRACT_SCALAR(item, \'$.batchDTO.batchFieldsDTO.cost\') AS FLOAT64) AS batch_cost, TIMESTAMP_MILLIS(CAST(JSON_EXTRACT_SCALAR(item, \'$.batchDTO.batchFieldsDTO.mfd\') AS INT64)) AS mfd_ts, TIMESTAMP_MILLIS(CAST(JSON_EXTRACT_SCALAR(item, \'$.batchDTO.batchFieldsDTO.expiryDate\') AS INT64)) AS expiry_ts, CAST(JSON_EXTRACT_SCALAR(item, \'$.batchDTO.batchFieldsDTO.recallFlag\') AS BOOL) AS recall_flag, JSON_EXTRACT_SCALAR(item, \'$.shippingPackageCode\') AS shipping_package_code, JSON_EXTRACT_SCALAR(item, \'$.shippingPackageStatus\') AS shipping_package_status FROM order_header oh, UNNEST(JSON_EXTRACT_ARRAY(oh.SALEORDERDTO, \'$.saleOrderItems\')) AS item; CREATE OR REPLACE TEMP TABLE shipping_packages AS SELECT oh.order_code, JSON_EXTRACT_SCALAR(pkg, \'$.code\') AS package_code, JSON_EXTRACT_SCALAR(pkg, \'$.status\') AS package_status, JSON_EXTRACT_SCALAR(pkg, \'$.courierStatus\') AS courier_status, JSON_EXTRACT_SCALAR(pkg, \'$.trackingStatus\') AS tracking_status, JSON_EXTRACT_SCALAR(pkg, \'$.shippingProvider\') AS shipping_provider, JSON_EXTRACT_SCALAR(pkg, \'$.shippingCourier\') AS shipping_courier, JSON_EXTRACT_SCALAR(pkg, \'$.shippingMethod\') AS shipping_method, JSON_EXTRACT_SCALAR(pkg, \'$.trackingNumber\') AS tracking_number, JSON_EXTRACT_SCALAR(pkg, \'$.trackingLink\') AS tracking_link, JSON_EXTRACT_SCALAR(pkg, \'$.shippingLabelLink\') AS shipping_label_link, JSON_EXTRACT_SCALAR(pkg, \'$.shippingManifestCode\') AS shipping_manifest_code, JSON_EXTRACT_SCALAR(pkg, \'$.invoiceCode\') AS invoice_code, JSON_EXTRACT_SCALAR(pkg, \'$.invoiceDisplayCode\') AS invoice_display_code, TIMESTAMP_MILLIS(CAST(JSON_EXTRACT_SCALAR(pkg, \'$.invoiceDate\') AS INT64)) AS invoice_date_ts, CAST(JSON_EXTRACT_SCALAR(pkg, \'$.actualWeight\') AS FLOAT64) AS actual_weight, CAST(JSON_EXTRACT_SCALAR(pkg, \'$.estimatedWeight\') AS FLOAT64) AS estimated_weight, CAST(JSON_EXTRACT_SCALAR(pkg, \'$.noOfItems\') AS INT64) AS no_of_items, CAST(JSON_EXTRACT_SCALAR(pkg, \'$.collectableAmount\') AS FLOAT64) AS collectable_amount, CAST(JSON_EXTRACT_SCALAR(pkg, \'$.collectedAmount\') AS FLOAT64) AS collected_amount, CAST(JSON_EXTRACT_SCALAR(pkg, \'$.paymentReconciled\') AS BOOL) AS is_payment_reconciled, JSON_EXTRACT_SCALAR(pkg, \'$.city\') AS package_city, TIMESTAMP_MILLIS(CAST(JSON_EXTRACT_SCALAR(pkg, \'$.created\') AS INT64)) AS package_created_timestamp, TIMESTAMP_MILLIS(CAST(JSON_EXTRACT_SCALAR(pkg, \'$.updated\') AS INT64)) AS package_updated_timestamp, TIMESTAMP_MILLIS(CAST(JSON_EXTRACT_SCALAR(pkg, \'$.dispatched\') AS INT64)) AS package_dispatched_timestamp, TIMESTAMP_MILLIS(CAST(JSON_EXTRACT_SCALAR(pkg, \'$.delivered\') AS INT64)) AS package_delivered_timestamp, JSON_EXTRACT(pkg, \'$.items\') AS pkg_items_json FROM order_header oh, UNNEST(JSON_EXTRACT_ARRAY(oh.SALEORDERDTO, \'$.shippingPackages\')) AS pkg; CREATE OR REPLACE TEMP TABLE package_items AS SELECT sp.order_code, sp.package_code, JSON_EXTRACT_SCALAR(pi, \'$.itemSku\') AS sku, CAST(JSON_EXTRACT_SCALAR(pi, \'$.quantity\') AS INT64) AS shippedQuantity FROM shipping_packages sp, UNNEST(JSON_EXTRACT_ARRAY(sp.pkg_items_json, \'$\')) AS pi; CREATE OR REPLACE TEMP TABLE order_returns AS WITH ret AS ( SELECT oh.order_code, r AS ret_json FROM order_header oh, UNNEST(JSON_EXTRACT_ARRAY(oh.SALEORDERDTO, \'$.returns\')) AS r ) SELECT ret.order_code, JSON_EXTRACT_SCALAR(ret.ret_json, \'$.code\') AS return_display_code, JSON_EXTRACT_SCALAR(ret.ret_json, \'$.statusCode\') AS return_status, JSON_EXTRACT_SCALAR(ret.ret_json, \'$.shippingProvider\') AS return_courier, JSON_EXTRACT_SCALAR(ret.ret_json, \'$.providerStatus\') AS return_provider_status, JSON_EXTRACT_SCALAR(ret.ret_json, \'$.trackingNumber\') AS return_tracking_number, TIMESTAMP_MILLIS(CAST(JSON_EXTRACT_SCALAR(ret.ret_json, \'$.inventoryReceivedDate\') AS INT64)) AS inventory_received_ts, TIMESTAMP_MILLIS(CAST(JSON_EXTRACT_SCALAR(ret.ret_json, \'$.returnCompletedDate\') AS INT64)) AS return_completed_ts, JSON_EXTRACT_SCALAR(ri, \'$.saleOrderItemCode\') AS saleOrderItemCode, JSON_EXTRACT_SCALAR(ri, \'$.itemSku\') AS return_item_sku, JSON_EXTRACT_SCALAR(ri, \'$.inventoryType\') AS inventory_type FROM ret, UNNEST(JSON_EXTRACT_ARRAY(ret.ret_json, \'$.returnItems\')) AS ri; CREATE OR REPLACE TABLE maplemonk.KA_UNICOMMERCE_fact_items_intermediate_final AS WITH item_pkg AS ( SELECT oi.order_code, oi.display_order_code, oi.marketplace, oi.source, oi.order_status, oi.currency, oi.order_created_ts, oi.order_updated_ts, oi.order_display_ts, oi.fulfillment_tat_ts, oi.billing_name, oi.billing_address_line1, oi.billing_address_line2, oi.billing_city, oi.billing_state, oi.pincode, oi.billing_country, oi.phone, oi.email, oi.saleOrderItemCode, oi.sales_order_item_id, oi.sku, oi.marketplace_sku, oi.product_name, oi.item_status, oi.channel_product_id, oi.selling_price, oi.shipping_price, oi.discount, oi.tax_igst, oi.total_price, oi.cod_charges, oi.suborder_quantity_raw, oi.warehouse_name, oi.facility_code, oi.shelf_code, oi.batch_code, oi.vendor_batch_number, oi.vendor_code, oi.batch_mrp, oi.batch_cost, oi.mfd_ts, oi.expiry_ts, oi.recall_flag, oi.shipping_package_code, oi.shipping_package_status, sp.package_code, sp.package_status, sp.courier_status, sp.tracking_status, sp.shipping_provider, sp.shipping_courier, sp.shipping_method, sp.tracking_number, sp.tracking_link, sp.shipping_label_link, sp.shipping_manifest_code, sp.invoice_code, sp.invoice_display_code, sp.invoice_date_ts, sp.actual_weight, sp.estimated_weight, sp.no_of_items, sp.collectable_amount, sp.collected_amount, sp.is_payment_reconciled, sp.package_city, sp.package_created_timestamp AS packed_at_ts, sp.package_dispatched_timestamp, sp.package_delivered_timestamp, sp.package_updated_timestamp, pi.shippedQuantity, CASE WHEN oi.is_cod THEN \'COD\' ELSE \'Prepaid\' END AS payment_mode, DATETIME(oi.order_display_ts, \"Asia/Kolkata\") AS order_date_ist, DATETIME(oi.order_updated_ts, \"Asia/Kolkata\") AS shipping_last_update_ist, DATETIME(sp.invoice_date_ts, \"Asia/Kolkata\") AS invoice_date_ist, DATETIME(sp.package_dispatched_timestamp, \"Asia/Kolkata\") AS dispatch_date_ist, DATETIME(sp.package_delivered_timestamp, \"Asia/Kolkata\") AS delivered_date_ist, CASE WHEN LOWER(oi.marketplace) LIKE \'%myntra%\' THEN SAFE_DIVIDE(pi.shippedQuantity, COUNT(*) OVER (PARTITION BY oi.order_code, oi.sku)) WHEN LOWER(oi.marketplace) LIKE \'%tata%\' THEN oi.suborder_quantity_raw / 1000 WHEN CAST(oi.suborder_quantity_raw AS INT64) = 0 THEN 1 ELSE oi.suborder_quantity_raw END AS PRE_SUBORDER_QUANTITY, CASE WHEN r.saleOrderItemCode IS NOT NULL THEN 1 ELSE 0 END AS return_flag, CASE WHEN r.saleOrderItemCode IS NOT NULL THEN CASE WHEN LOWER(oi.marketplace) LIKE \'%myntra%\' THEN pi.shippedQuantity ELSE oi.suborder_quantity_raw END ELSE 0 END AS return_quantity, SUM(oi.total_price) OVER (PARTITION BY oi.order_code, sp.package_code) AS item_total_by_pkg, sp.collectable_amount - SUM(oi.total_price) OVER (PARTITION BY oi.order_code, sp.package_code) AS delta_collectable, CASE WHEN sp.package_delivered_timestamp IS NOT NULL THEN sp.collectable_amount ELSE 0 END AS cod_due_when_delivered, CASE WHEN ROW_NUMBER() OVER (PARTITION BY oi.phone ORDER BY DATETIME(oi.order_display_ts, \"Asia/Kolkata\") ASC) = 1 THEN \'New\' ELSE \'Repeat\' END AS new_customer_flag, FIRST_VALUE(oi.product_name) OVER (PARTITION BY oi.phone ORDER BY DATETIME(oi.order_display_ts, \"Asia/Kolkata\") ASC) AS acquisition_product, CASE WHEN UPPER(oi.order_status) = \'COMPLETE\' THEN DATE_DIFF(DATE(sp.package_delivered_timestamp), DATE(DATETIME(oi.order_display_ts, \"Asia/Kolkata\")), DAY) ELSE DATE_DIFF(CURRENT_DATE(), DATE(DATETIME(oi.order_display_ts, \"Asia/Kolkata\")), DAY) END AS days_in_shipment FROM order_items oi LEFT JOIN shipping_packages sp ON oi.order_code = sp.order_code AND oi.shipping_package_code = sp.package_code LEFT JOIN package_items pi ON oi.order_code = pi.order_code AND oi.shipping_package_code = pi.package_code AND oi.sku = pi.sku LEFT JOIN order_returns r ON oi.order_code = r.order_code AND oi.saleOrderItemCode = r.saleOrderItemCode ) SELECT * FROM item_pkg; CREATE OR REPLACE TABLE maplemonk.KA_customerID_test_Final AS WITH base AS ( SELECT DISTINCT SUBSTR(REGEXP_REPLACE(REPLACE(phone, \' \', \'\'), r\'[^0-9]\', \'\'), -10) AS contact_num, email FROM maplemonk.KA_UNICOMMERCE_fact_items_intermediate_final ), new_phone_numbers AS ( SELECT contact_num, 9700000000 + ROW_NUMBER() OVER (ORDER BY contact_num) AS maple_monk_id FROM base WHERE contact_num IS NOT NULL AND contact_num <> \'\' ), id_stage AS ( SELECT e.contact_num, e.email, COALESCE(n.maple_monk_id, 9800000000 + ROW_NUMBER() OVER (ORDER BY e.email)) AS maple_monk_id FROM base e LEFT JOIN new_phone_numbers n ON n.contact_num = e.contact_num ) SELECT contact_num, email, CASE WHEN email IS NOT NULL AND email <> \'\' THEN MIN(maple_monk_id) OVER (PARTITION BY email) ELSE maple_monk_id END AS maple_monk_id FROM id_stage WHERE COALESCE(contact_num, email) IS NOT NULL; CREATE OR REPLACE TABLE maplemonk.KA_unicommerce_fact_items AS SELECT c.maple_monk_id AS customer_id, f.*, MIN(DATETIME(f.order_display_ts, \"Asia/Kolkata\")) OVER (PARTITION BY c.maple_monk_id) AS acquisition_date FROM maplemonk.KA_UNICOMMERCE_fact_items_intermediate_final f LEFT JOIN ( SELECT DISTINCT contact_num AS phone, maple_monk_id FROM maplemonk.KA_customerID_test_Final ) c ON REPLACE(c.phone, \' \', \'\') = REPLACE(f.phone, \' \', \'\') WHERE DATETIME(f.order_display_ts, \"Asia/Kolkata\") IS NOT NULL; CREATE OR REPLACE TABLE maplemonk.KA_unicommerce_fact_items_TEMP_Category AS WITH sku_master AS ( SELECT MARKETPLACE_SKU AS skucode, name, category, category_code AS sub_category, MRP, commonsku, TAX_RATE FROM maplemonk.final_sku_master WHERE LOWER(data_source) LIKE \'%unicommerce%\' QUALIFY ROW_NUMBER() OVER ( PARTITION BY LOWER(IFNULL(TRIM(MARKETPLACE_SKU), \'\')) ORDER BY LOWER(IFNULL(TRIM(commonsku), \'\')) DESC ) = 1 ), enriched AS ( SELECT fi.*, sm.skucode AS SKU_CODE, UPPER(sm.name) AS PRODUCT_NAME_Final, UPPER(sm.category) AS Product_Category, UPPER(sm.sub_category) AS Product_Sub_Category, sm.TAX_RATE AS FINAL_TAX_RATE, UPPER(sm.commonsku) AS commonsku, CASE WHEN SAFE_CAST(ARRAY_REVERSE(SPLIT(sm.commonsku, \"-\"))[ORDINAL(1)] AS INT64) IS NULL THEN PRE_SUBORDER_QUANTITY ELSE SAFE_DIVIDE(PRE_SUBORDER_QUANTITY, SAFE_CAST(ARRAY_REVERSE(SPLIT(sm.commonsku, \"-\"))[ORDINAL(1)] AS INT64)) END AS SUBORDER_QUANTITY FROM maplemonk.KA_unicommerce_fact_items fi LEFT JOIN sku_master sm ON LOWER(fi.marketplace_sku) = LOWER(sm.skucode) ) SELECT * FROM enriched; CREATE OR REPLACE TABLE maplemonk.KA_unicommerce_fact_items AS SELECT e.*, e.display_order_code AS reference_code, e.tracking_number AS AWB, COALESCE(e.shipping_courier, e.shipping_provider) AS courier, COALESCE(e.delivered_date_ist, DATETIME(e.package_delivered_timestamp, \"Asia/Kolkata\")) AS Delivered_Date, COALESCE(e.dispatch_date_ist, DATETIME(e.package_dispatched_timestamp, \"Asia/Kolkata\")) AS Dispatch_date, COALESCE(e.shipping_last_update_ist, DATETIME(e.order_updated_ts, \"Asia/Kolkata\")) AS SHIPPING_LAST_UPDATE_DATE, COALESCE(e.tracking_status, e.courier_status, e.package_status, e.shipping_package_status) AS shipping_status, e.channel_product_id AS product_id, e.billing_name AS name, UPPER(e.billing_city) AS city, UPPER(e.billing_state) AS state FROM maplemonk.KA_unicommerce_fact_items_TEMP_Category e;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            